<style>
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 1.75rem;
  margin-top: 1.5rem;
  max-width: 1106px;
  margin-left: auto;
  margin-right: auto;
  justify-content: center;
}

.team-card {
  display: flex;
  flex-direction: column;
  /* border: 1px solid #e5e7eb; */
  border-radius: 8px;
  overflow: hidden;
  background-color: #ffffff;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.team-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
}

.team-card-img-link {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  background-color: transparent;
}

.team-card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  margin-top: 0px;
  margin-bottom: 0px;
  border-radius: 8px;
}

.team-card-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.team-card-name {
  margin: 0 0 0.35rem 0;
  font-size: 1.2rem;
  color: var(--accent-main);
  line-height: 1.3;
}

.team-card-name a {
  text-decoration: none;
  color: inherit;
}

.team-card-name a:hover {
  text-decoration: underline;
}

.team-card-position {
  font-size: 0.9rem;
  font-weight: 600;
  color: #4b5563;
  margin-bottom: 0.75rem;
}

.team-card-desc {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.5;
  color: #374151;
  text-align: left;
}
</style>
```




